function getPreviousBackups() {
  return typeof PREVIOUS_BACKUPS !== 'undefined' ? PREVIOUS_BACKUPS : [];
}

function getLatestBackup() {
  const backups = getPreviousBackups();
  return backups.find(b => b.isLatest) || backups[0] || null;
}

function getBackupById(id) {
  return getPreviousBackups().find(b => b.id === id) || null;
}
